function parseMonosaccharides(glycan) {
  const result = [];
  const regex = /([A-Za-z]+)\\((\\d+)\\)/g;
  let match;

  while ((match = regex.exec(glycan)) !== null) {
    result.push({
      type: match[1],
      count: parseInt(match[2])
    });
  }

  return result;
}

